      try { n = fs.readSync(e.fd, dst, 0, count, e.pos); } catch (x) { gpr[2] = -5; return; }
      e.pos += n;
      gpr[2] = n | 0;
      return;
    }
    case 1: {   // write(fd, buf, count)
      const count = a2 >>> 0;
      const src = Buffer.from(MEM, a1 >>> 0, count);
      const hostFd = (a0 === 2) ? 2 : 1;
      try { fs.writeSync(hostFd, src, 0, count); } catch (x) {}
      gpr[2] = count | 0;
      return;
    }
    case 2: {   // open(path, flags, mode)
      let p = cstr(a0 >>> 0);
      const flags = a1 | 0;
      const writing = (flags & 3) !== 0 || (flags & 0x40) !== 0;
      let fd;
      try {
        fd = fs.openSync(p, writing ? 'w' : 'r');
      } catch (x) {
        try { fd = fs.openSync(path.join(__dirname, p), writing ? 'w' : 'r'); }
        catch (y) { gpr[2] = -2; return; }    // ENOENT
      }
      let size = 0;
      try { size = fs.fstatSync(fd).size; } catch (x) {}
      const g = nextFd++;
      fdtab.set(g, { fd, pos: 0, size });
      gpr[2] = g | 0;
      return;
    }
    case 3: {   // close(fd)
      const e = fdtab.get(a0 >>> 0);
      if (e) { try { fs.closeSync(e.fd); } catch (x) {} fdtab.delete(a0 >>> 0); }
      gpr[2] = 0;
      return;
    }
    case 8: {   // lseek(fd, offset, whence)
      const e = fdtab.get(a0 >>> 0);
      if (!e) { gpr[2] = -9; return; }
