      if (whence === 0) e.pos = off >>> 0;
      else if (whence === 1) e.pos = (e.pos + off) >>> 0;
      else if (whence === 2) e.pos = (e.size + off) >>> 0;
      else { gpr[2] = -22; return; }
      gpr[2] = e.pos | 0;
      return;
    }
    case 74:    // fsync
      gpr[2] = 0; return;
    case 60:    // exit
      process.exit(a0 & 0xff);
      return;
    case 201: { // time(tloc)
      const now = Math.floor(Date.now() / 1000) | 0;
      if (a0 !== 0) U32[(a0 >>> 0) >>> 2] = now >>> 0;
      gpr[2] = now;
      return;
    }
    default:
      process.stderr.write(`[vm] unhandled syscall ${num}\n`);
      gpr[2] = -38;   // ENOSYS
      return;
  }
}

// ---------------------------------------------------------------------------
// Main execution loop
// ---------------------------------------------------------------------------
function run() {
  for (;;) {
    gpr[0] = 0;
    const cpc = pc;
    if (cpc === DG_DRAWFRAME) saveFrame();

    const inst = U32[cpc >>> 2];
    pc = npc; npc = (pc + 4) | 0;

    const op = inst >>> 26;
    switch (op) {
      case 0x00: {   // SPECIAL
        const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31,
              rd = (inst >>> 11) & 31, sa = (inst >>> 6) & 31, funct = inst & 63;
        switch (funct) {
          case 0x00: gpr[rd] = gpr[rt] << sa; break;                    // sll
          case 0x02:                                                    // srl / rotr
            if ((inst >>> 21) & 1) { const t = gpr[rt]; gpr[rd] = sa ? ((t >>> sa) | (t << (32 - sa))) : t; }
            else gpr[rd] = gpr[rt] >>> sa;
            break;
          case 0x03: gpr[rd] = gpr[rt] >> sa; break;                    // sra
          case 0x04: gpr[rd] = gpr[rt] << (gpr[rs] & 31); break;        // sllv
          case 0x06:                                                    // srlv / rotrv
            if ((inst >>> 6) & 1) { const s = gpr[rs] & 31, t = gpr[rt]; gpr[rd] = s ? ((t >>> s) | (t << (32 - s))) : t; }
            else gpr[rd] = gpr[rt] >>> (gpr[rs] & 31);
            break;
          case 0x07: gpr[rd] = gpr[rt] >> (gpr[rs] & 31); break;        // srav
          case 0x08: npc = gpr[rs]; break;                              // jr
          case 0x09: gpr[rd] = (cpc + 8) | 0; npc = gpr[rs]; break;     // jalr
          case 0x0a: if (gpr[rt] === 0) gpr[rd] = gpr[rs]; break;       // movz
          case 0x0b: if (gpr[rt] !== 0) gpr[rd] = gpr[rs]; break;       // movn
          case 0x0c: doSyscall(); break;                               // syscall
          case 0x0d: process.stderr.write('[vm] break\n'); process.exit(1); break;
          case 0x0f: break;                                            // sync
          case 0x10: gpr[rd] = HI; break;                              // mfhi
          case 0x11: HI = gpr[rs]; break;                              // mthi
          case 0x12: gpr[rd] = LO; break;                              // mflo
          case 0x13: LO = gpr[rs]; break;                              // mtlo
          case 0x18: smul(gpr[rs], gpr[rt]); break;                    // mult
          case 0x19: umul(gpr[rs], gpr[rt]); break;                    // multu
          case 0x1a: {                                                 // div
            const a = gpr[rs], b = gpr[rt];
            if (b !== 0) { LO = (a / b) | 0; HI = (a % b) | 0; } else { LO = 0; HI = 0; }
            break;
          }
          case 0x1b: {                                                 // divu
            const a = gpr[rs] >>> 0, b = gpr[rt] >>> 0;
            if (b !== 0) { LO = (a / b) >>> 0; HI = (a % b) >>> 0; } else { LO = 0; HI = 0; }
            break;
          }
          case 0x20: gpr[rd] = (gpr[rs] + gpr[rt]) | 0; break;         // add
          case 0x21: gpr[rd] = (gpr[rs] + gpr[rt]) | 0; break;         // addu
          case 0x22: gpr[rd] = (gpr[rs] - gpr[rt]) | 0; break;         // sub
          case 0x23: gpr[rd] = (gpr[rs] - gpr[rt]) | 0; break;         // subu
          case 0x24: gpr[rd] = gpr[rs] & gpr[rt]; break;               // and
          case 0x25: gpr[rd] = gpr[rs] | gpr[rt]; break;               // or
          case 0x26: gpr[rd] = gpr[rs] ^ gpr[rt]; break;               // xor
          case 0x27: gpr[rd] = ~(gpr[rs] | gpr[rt]); break;            // nor
          case 0x2a: gpr[rd] = (gpr[rs] < gpr[rt]) ? 1 : 0; break;      // slt
          case 0x2b: gpr[rd] = ((gpr[rs] >>> 0) < (gpr[rt] >>> 0)) ? 1 : 0; break; // sltu
          case 0x34: /* teq */ break;                                  // trap-if-equal (ignore)
          case 0x01: {   // MOVCI (movf/movt integer)
            const cc = (inst >>> 18) & 7, tf = (inst >>> 16) & 1;
            if (fcc[cc] === tf) gpr[rd] = gpr[rs];
            break;
          }
          default: unimpl(inst, cpc);
        }
        break;
      }
      case 0x01: {   // REGIMM
        const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31;
        const target = (cpc + 4 + (((inst << 16) >> 16) << 2)) | 0;
        switch (rt) {
          case 0x00: if (gpr[rs] < 0) npc = target; break;             // bltz
          case 0x01: if (gpr[rs] >= 0) npc = target; break;            // bgez
          case 0x10: gpr[31] = (cpc + 8) | 0; if (gpr[rs] < 0) npc = target; break;  // bltzal
          case 0x11: gpr[31] = (cpc + 8) | 0; if (gpr[rs] >= 0) npc = target; break; // bgezal
          default: unimpl(inst, cpc);
        }
