      }
      case 0x02: npc = ((cpc & 0xf0000000) | ((inst & 0x3ffffff) << 2)) | 0; break;  // j
      case 0x03: gpr[31] = (cpc + 8) | 0; npc = ((cpc & 0xf0000000) | ((inst & 0x3ffffff) << 2)) | 0; break; // jal
      case 0x04: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31;
        if (gpr[rs] === gpr[rt]) npc = (cpc + 4 + (((inst << 16) >> 16) << 2)) | 0; break; } // beq
      case 0x05: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31;
        if (gpr[rs] !== gpr[rt]) npc = (cpc + 4 + (((inst << 16) >> 16) << 2)) | 0; break; } // bne
      case 0x06: { const rs = (inst >>> 21) & 31;
        if (gpr[rs] <= 0) npc = (cpc + 4 + (((inst << 16) >> 16) << 2)) | 0; break; }        // blez
      case 0x07: { const rs = (inst >>> 21) & 31;
        if (gpr[rs] > 0) npc = (cpc + 4 + (((inst << 16) >> 16) << 2)) | 0; break; }         // bgtz
      case 0x09: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31;
        gpr[rt] = (gpr[rs] + ((inst << 16) >> 16)) | 0; break; }                             // addiu
      case 0x08: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31;
        gpr[rt] = (gpr[rs] + ((inst << 16) >> 16)) | 0; break; }                             // addi (no trap)
      case 0x0a: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31;
        gpr[rt] = (gpr[rs] < ((inst << 16) >> 16)) ? 1 : 0; break; }                          // slti
      case 0x0b: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31;
        gpr[rt] = ((gpr[rs] >>> 0) < (((inst << 16) >> 16) >>> 0)) ? 1 : 0; break; }           // sltiu
      case 0x0c: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31;
        gpr[rt] = gpr[rs] & (inst & 0xffff); break; }                                        // andi
      case 0x0d: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31;
        gpr[rt] = gpr[rs] | (inst & 0xffff); break; }                                        // ori
      case 0x0e: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31;
        gpr[rt] = gpr[rs] ^ (inst & 0xffff); break; }                                        // xori
      case 0x0f: { const rt = (inst >>> 16) & 31; gpr[rt] = (inst & 0xffff) << 16; break; }   // lui

      case 0x1c: {   // SPECIAL2
        const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31, rd = (inst >>> 11) & 31, funct = inst & 63;
        switch (funct) {
          case 0x02: gpr[rd] = Math.imul(gpr[rs], gpr[rt]); break;      // mul
          case 0x00: { smul(gpr[rs], gpr[rt]); /* madd: not used */ } break;
          default: unimpl(inst, cpc);
        }
        break;
      }
      case 0x1f: {   // SPECIAL3
        const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31, rd = (inst >>> 11) & 31,
              sa = (inst >>> 6) & 31, funct = inst & 63;
        if (funct === 0x00) {                                          // ext
          const size = rd + 1, pos = sa;
          const mask = size >= 32 ? 0xffffffff : ((1 << size) - 1);
          gpr[rt] = (gpr[rs] >>> pos) & mask;
        } else if (funct === 0x04) {                                   // ins
          const msb = rd, lsb = sa, size = msb - lsb + 1;
          const mask = size >= 32 ? 0xffffffff : ((1 << size) - 1);
          gpr[rt] = ((gpr[rt] & ~(mask << lsb)) | ((gpr[rs] & mask) << lsb)) | 0;
        } else if (funct === 0x20) {                                   // BSHFL
          if (sa === 0x02) { const t = gpr[rt]; gpr[rd] = (((t & 0x00ff00ff) << 8) | ((t >>> 8) & 0x00ff00ff)) | 0; } // wsbh
          else if (sa === 0x10) gpr[rd] = (gpr[rt] << 24) >> 24;       // seb
          else if (sa === 0x18) gpr[rd] = (gpr[rt] << 16) >> 16;       // seh
          else unimpl(inst, cpc);
        } else unimpl(inst, cpc);
        break;
      }

      // ---- loads ----
      case 0x20: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // lb
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; gpr[rt] = (U8[a] << 24) >> 24; break; }
      case 0x21: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // lh
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; gpr[rt] = ((U8[a] | (U8[a + 1] << 8)) << 16) >> 16; break; }
      case 0x23: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // lw
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; gpr[rt] = U32[a >>> 2] | 0; break; }
      case 0x24: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // lbu
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; gpr[rt] = U8[a]; break; }
      case 0x25: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // lhu
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; gpr[rt] = U8[a] | (U8[a + 1] << 8); break; }
      case 0x22: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // lwl
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; const al = a & 3;
        const w = U32[(a & ~3) >>> 2]; const shift = (3 - al) * 8;
        const mask = (0xffffffff << shift) >>> 0;
        gpr[rt] = ((gpr[rt] & ~mask) | ((w << shift) & mask)) | 0; break; }
      case 0x26: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // lwr
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; const al = a & 3;
        const w = U32[(a & ~3) >>> 2]; const shift = al * 8;
        const lomask = shift === 0 ? 0xffffffff : (0xffffffff >>> shift);
        gpr[rt] = ((gpr[rt] & ~lomask) | ((w >>> shift) & lomask)) | 0; break; }

      // ---- stores ----
      case 0x28: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // sb
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; U8[a] = gpr[rt]; break; }
      case 0x29: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // sh
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; U8[a] = gpr[rt] & 0xff; U8[a + 1] = (gpr[rt] >>> 8) & 0xff; break; }
      case 0x2b: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // sw
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; U32[a >>> 2] = gpr[rt]; break; }
      case 0x2a: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // swl
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; const al = a & 3;
        const idx = (a & ~3) >>> 2; const w = U32[idx]; const shift = (3 - al) * 8;
        const lomask = shift === 0 ? 0xffffffff : (0xffffffff >>> shift);
        U32[idx] = ((w & ~lomask) | ((gpr[rt] >>> shift) & lomask)) >>> 0; break; }
      case 0x2e: { const rs = (inst >>> 21) & 31, rt = (inst >>> 16) & 31; // swr
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; const al = a & 3;
        const idx = (a & ~3) >>> 2; const w = U32[idx]; const shift = al * 8;
        const himask = (0xffffffff << shift) >>> 0;
        U32[idx] = ((w & ~himask) | ((gpr[rt] << shift) & himask)) >>> 0; break; }

      // ---- coprocessor 1 loads/stores ----
      case 0x31: { const rs = (inst >>> 21) & 31, ft = (inst >>> 16) & 31; // lwc1
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; fgpr[ft] = U32[a >>> 2]; break; }
      case 0x39: { const rs = (inst >>> 21) & 31, ft = (inst >>> 16) & 31; // swc1
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; U32[a >>> 2] = fgpr[ft]; break; }
      case 0x35: { const rs = (inst >>> 21) & 31, ft = (inst >>> 16) & 31; // ldc1
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; fgpr[ft] = U32[a >>> 2]; fgpr[ft + 1] = U32[(a + 4) >>> 2]; break; }
      case 0x3d: { const rs = (inst >>> 21) & 31, ft = (inst >>> 16) & 31; // sdc1
        const a = (gpr[rs] + ((inst << 16) >> 16)) >>> 0; U32[a >>> 2] = fgpr[ft]; U32[(a + 4) >>> 2] = fgpr[ft + 1]; break; }

      case 0x11: cop1(inst, cpc); break;   // COP1

      default: unimpl(inst, cpc);
    }
  }
}

// ---------------------------------------------------------------------------
// Coprocessor 1 (FPU)
// ---------------------------------------------------------------------------
function cop1(inst, cpc) {
  const rsf = (inst >>> 21) & 31;   // format / sub-op
  const ft  = (inst >>> 16) & 31;
  const fs  = (inst >>> 11) & 31;
  const fd  = (inst >>> 6) & 31;
  const funct = inst & 63;
  switch (rsf) {
    case 0x00: gpr[ft] = fgpr[fs] | 0; return;              // mfc1
    case 0x04: fgpr[fs] = gpr[ft]; return;                  // mtc1
    case 0x03: gpr[ft] = fgpr[fs + 1] | 0; return;          // mfhc1
    case 0x07: fgpr[fs + 1] = gpr[ft]; return;              // mthc1
    case 0x02: gpr[ft] = 0; return;                         // cfc1 (FCSR ~ 0)
    case 0x06: return;                                      // ctc1 (ignore)
    case 0x08: {                                            // BC1F/BC1T
      const cc = (inst >>> 18) & 7, tf = (inst >>> 16) & 1;
      if (fcc[cc] === tf) npc = (cpc + 4 + (((inst << 16) >> 16) << 2)) | 0;
      return;
    }
    case 0x10: fpArith(funct, inst, fd, fs, ft, false); return;  // S
    case 0x11: fpArith(funct, inst, fd, fs, ft, true);  return;  // D
    case 0x14: {   // W (integer source) -> convert
      if (funct === 0x20) writeS(fd, readWfp(fs));         // cvt.s.w
      else if (funct === 0x21) writeD(fd, readWfp(fs));    // cvt.d.w
      else unimpl(inst, cpc);
      return;
    }
    default: unimpl(inst, cpc);
  }
}
function fpArith(funct, inst, fd, fs, ft, isD) {
  const rd = isD ? readD : readS;
  const wr = isD ? writeD : writeS;
  switch (funct) {
    case 0x00: wr(fd, rd(fs) + rd(ft)); return;             // add
    case 0x01: wr(fd, rd(fs) - rd(ft)); return;             // sub
    case 0x02: wr(fd, rd(fs) * rd(ft)); return;             // mul
    case 0x03: wr(fd, rd(fs) / rd(ft)); return;             // div
    case 0x04: wr(fd, Math.sqrt(rd(fs))); return;           // sqrt
    case 0x05: wr(fd, Math.abs(rd(fs))); return;            // abs
    case 0x06: wr(fd, rd(fs)); return;                      // mov
    case 0x07: wr(fd, -rd(fs)); return;                     // neg
    case 0x0d: fgpr[fd] = Math.trunc(rd(fs)) | 0; return;   // trunc.w
    case 0x20: writeS(fd, rd(fs)); return;                  // cvt.s
    case 0x21: writeD(fd, rd(fs)); return;                  // cvt.d
    case 0x24: fgpr[fd] = Math.round(rd(fs)) | 0; return;   // cvt.w
    case 0x11: {                                            // movf/movt.fmt
      const cc = (inst >>> 18) & 7, tf = (inst >>> 16) & 1;
      if (fcc[cc] === tf) wr(fd, rd(fs));
      return;
    }
    default:
      if (funct >= 0x30) {                                  // c.cond.fmt
        const cc = (inst >>> 8) & 7;
        const a = rd(fs), b = rd(ft);
        const cond = funct & 0xf;
        let res = false;
        // low bit set -> less-than component; bit1 -> equal component
        if (cond & 4) res = res || (a < b);
        if (cond & 2) res = res || (a === b);
        fcc[cc] = res ? 1 : 0;
        return;
      }
      unimpl(inst, 0);
  }
}

function unimpl(inst, cpc) {
  process.stderr.write(`[vm] unimplemented insn 0x${(inst >>> 0).toString(16)} at 0x${(cpc >>> 0).toString(16)}\n`);
  process.exit(2);
}

run();

#!/usr/bin/env node
// MIPS32r2 (little-endian, o32) interpreter for doomgeneric_mips.
// Runs the static ELF, services the syscalls it issues, and persists each
// rendered frame to /tmp/frame.bmp (plus numbered copies).
'use strict';
const fs = require('fs');
const path = require('path');

const ELF_PATH = process.argv[2] || path.join(__dirname, 'doomgeneric_mips');

// ---------------------------------------------------------------------------
// Memory
// ---------------------------------------------------------------------------
const MEM_TOP    = 0x41000000;        // ~1.09 GB (covers the guest's 1 GB static heap)
const STACK_TOP  = 0x40E00000;

const MEM = new ArrayBuffer(MEM_TOP);
const U8  = new Uint8Array(MEM);
const U32 = new Uint32Array(MEM);     // index by (addr >>> 2)

// ---------------------------------------------------------------------------
// ELF loader
// ---------------------------------------------------------------------------
function rd32(buf, off) { return buf.readUInt32LE(off); }
function rd16(buf, off) { return buf.readUInt16LE(off); }

const elf = fs.readFileSync(ELF_PATH);
if (!(elf[0] === 0x7f && elf[1] === 0x45 && elf[2] === 0x4c && elf[3] === 0x46))
  throw new Error('not an ELF');
const entry = rd32(elf, 24);
const phoff = rd32(elf, 28);
const phentsize = rd16(elf, 42);
const phnum = rd16(elf, 44);
for (let i = 0; i < phnum; i++) {
  const o = phoff + i * phentsize;
  const p_type   = rd32(elf, o);
  const p_offset = rd32(elf, o + 4);
  const p_vaddr  = rd32(elf, o + 8);
  const p_filesz = rd32(elf, o + 16);
  if (p_type === 1 && p_filesz > 0) {           // PT_LOAD
    elf.copy(U8, p_vaddr, p_offset, p_offset + p_filesz);
  }
}

// reginfo gp value (used as an ordinary register by this static binary)
const GP_VALUE = 0x47d090;

// ---------------------------------------------------------------------------
// CPU state
// ---------------------------------------------------------------------------
const gpr = new Int32Array(32);
let HI = 0, LO = 0;
let pc = entry;
let npc = (entry + 4) | 0;

gpr[29] = (STACK_TOP - 16) | 0;   // $sp
gpr[28] = GP_VALUE | 0;           // $gp
gpr[31] = 0;                      // $ra

// FPU: 32 raw 32-bit registers (FR=0 model, doubles use even/odd pairs)
const fgpr = new Uint32Array(32);
const fcc  = new Uint8Array(8);
const _sb  = new ArrayBuffer(8);
const _u32 = new Uint32Array(_sb);
const _i32 = new Int32Array(_sb);
const _f32 = new Float32Array(_sb);
const _f64 = new Float64Array(_sb);
function readS(i)      { _u32[0] = fgpr[i]; return _f32[0]; }
function writeS(i, v)  { _f32[0] = v; fgpr[i] = _u32[0]; }
function readD(i)      { _u32[0] = fgpr[i]; _u32[1] = fgpr[i + 1]; return _f64[0]; }
function writeD(i, v)  { _f64[0] = v; fgpr[i] = _u32[0]; fgpr[i + 1] = _u32[1]; }
function readWfp(i)    { _u32[0] = fgpr[i]; return _i32[0]; }

// ---------------------------------------------------------------------------
// 64-bit multiply helpers (avoid BigInt on the hot path)
// ---------------------------------------------------------------------------
function umul(a, b) {                       // a,b as unsigned 32
  a = a >>> 0; b = b >>> 0;
  const al = a & 0xffff, ah = a >>> 16;
  const bl = b & 0xffff, bh = b >>> 16;
  const ll = al * bl;
